import { SendMailOptions } from 'nodemailer';

export const PROJECT_BRAND_NAME = 'AI Self-Heal Platform';
export const PROJECT_BRAND_TAGLINE = 'Nền tảng Giám sát Hạ tầng Kubernetes & Tự Phục Hồi Bằng AI';
export const LOGO_CID = 'selfheal-logo';
export const LOGO_PNG_BASE64 = '';
export const LOGO_DATA_URI = `data:image/png;base64,${LOGO_PNG_BASE64}`;

export const getLogoAttachment = (): NonNullable<SendMailOptions['attachments']>[number] => ({
  filename: 'selfheal-logo.png',
  content: Buffer.from(LOGO_PNG_BASE64, 'base64'),
  cid: LOGO_CID,
  contentDisposition: 'inline',
  contentType: 'image/png',
});

export interface BrandedEmailLayoutOptions {
  pageTitle: string;
  headerBg?: string;
  accentColor?: string;
  bodyBg?: string;
  containerBorder?: string;
  maxWidth?: number;
  badgeText?: string;
  badgeBg?: string;
  badgeColor?: string;
  headerTitle: string;
  headerSubtitle: string;
  purposeTitle?: string;
  purposeText: string;
  purposeBg?: string;
  purposeBorder?: string;
  purposeTextColor?: string;
  bodyHtml: string;
  footerExtraHtml?: string;
}

const escapeAttr = (v: string): string =>
  String(v || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

/**
 * Khung Email HTML thống nhất toàn hệ thống AI Self-Heal Platform:
 * - Gắn logo dự án qua CID (selfheal-logo) tương thích Gmail/Outlook/Apple Mail
 * - Có khung giới thiệu Mục đích thư giúp người nhận nắm ngay lý do nhận thư & hành động cần làm
 */
export function renderBrandedEmailLayout(opts: BrandedEmailLayoutOptions): string {
  const headerBg = opts.headerBg || 'linear-gradient(135deg, #0f172a 0%, #064e3b 100%)';
  const accentColor = opts.accentColor || '#10b981';
  const bodyBg = opts.bodyBg || '#f1f5f9';
  const containerBorder = opts.containerBorder || '#e2e8f0';
  const maxWidth = opts.maxWidth || 620;
  const purposeBg = opts.purposeBg || '#ecfdf5';
  const purposeBorder = opts.purposeBorder || '#10b981';
  const purposeTextColor = opts.purposeTextColor || '#065f46';

  return `<!DOCTYPE html>
<html lang="vi">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${escapeAttr(opts.pageTitle)}</title>
</head>
<body style="margin:0; padding:24px 12px; background-color:${bodyBg}; font-family:-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; color:#1e293b;">
  <table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0">
    <tr>
      <td align="center">
        <div style="max-width:${maxWidth}px; margin:0 auto; background-color:#ffffff; border-radius:14px; overflow:hidden; border:1px solid ${containerBorder}; box-shadow:0 8px 28px rgba(15, 23, 42, 0.08); text-align:left;">
          <div style="background:${headerBg}; padding:22px 24px; color:#ffffff; border-bottom:3px solid ${accentColor};">
            <table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0">
              <tr>
                <td width="64" valign="middle" style="padding-right:14px;">
                  <div style="width:52px; height:52px; border-radius:12px; background-color:rgba(255,255,255,0.12); border:1px solid rgba(255,255,255,0.22); padding:4px; text-align:center;">
                    <img src="cid:${LOGO_CID}" alt="${PROJECT_BRAND_NAME}" width="44" height="44" style="display:block; width:44px; height:44px; border-radius:8px; margin:0 auto;" />
                  </div>
                </td>
                <td valign="middle">
                  ${opts.badgeText ? `<div style="display:inline-block; background:${opts.badgeBg || 'rgba(16, 185, 129, 0.2)'}; border:1px solid rgba(255,255,255,0.32); color:${opts.badgeColor || '#ffffff'}; font-size:10.5px; font-weight:800; letter-spacing:0.6px; text-transform:uppercase; padding:3px 9px; border-radius:999px; margin-bottom:6px;">${escapeAttr(opts.badgeText)}</div><br/>` : ''}
                  <div style="font-size:12px; font-weight:700; color:#a7f3d0; letter-spacing:0.4px; text-transform:uppercase;">${PROJECT_BRAND_NAME}</div>
                  <h1 style="margin:4px 0 0; font-size:20px; font-weight:800; line-height:1.3; color:#ffffff;">${opts.headerTitle}</h1>
                  <p style="margin:4px 0 0; font-size:13px; color:#e2e8f0; line-height:1.4;">${opts.headerSubtitle}</p>
                </td>
              </tr>
            </table>
          </div>
          <div style="padding:24px 24px 20px; color:#334155; font-size:14px; line-height:1.6;">
            <div style="background-color:${purposeBg}; border:1px solid ${purposeBorder}33; border-left:4px solid ${purposeBorder}; border-radius:8px; padding:12px 14px; margin-bottom:20px; font-size:13px; color:${purposeTextColor}; line-height:1.5;">
              <strong style="display:block; margin-bottom:3px; font-size:12px; text-transform:uppercase; letter-spacing:0.3px;">${opts.purposeTitle || 'Mục đích thư'}</strong>
              <span>${opts.purposeText}</span>
            </div>
            ${opts.bodyHtml}
          </div>
          <div style="background-color:#f8fafc; padding:18px 24px; border-top:1px solid #e2e8f0; font-size:12px; color:#64748b; text-align:center; line-height:1.55;">
            <p style="margin:0 0 4px; font-weight:700; color:#334155;">${PROJECT_BRAND_NAME} &bull; ${PROJECT_BRAND_TAGLINE}</p>
            ${opts.footerExtraHtml ? `<div style="margin:0 0 4px;">${opts.footerExtraHtml}</div>` : ''}
            <p style="margin:0; font-size:11px; color:#94a3b8;">&copy; ${new Date().getFullYear()} ${PROJECT_BRAND_NAME}. Giám sát eBPF &bull; Chẩn đoán AI &bull; Tự phục hồi hạ tầng Kubernetes an toàn.</p>
          </div>
        </div>
      </td>
    </tr>
  </table>
</body>
</html>`;
}
